import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { BookOpen, Copy, Download, KeyRound } from 'lucide-react';
import toast from 'react-hot-toast';
import api from '../api';

// Public API reference, rendered from the OpenAPI description generated by the server
const METHOD_CLS = { get: 'bg-sky-500/15 text-sky-400 border-sky-500/30', post: 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30' };

// `code` spans in descriptions
const Rich = ({ text }) => String(text || '').split(/(`[^`]+`)/g).map((p, i) => (p.startsWith('`')
  ? <code key={i} className="px-1 py-0.5 rounded bg-overlay/6 text-ink-1 text-[0.85em]">{p.slice(1, -1)}</code>
  : <React.Fragment key={i}>{p}</React.Fragment>));

function CodeBlock({ code }) {
  const copy = () => navigator.clipboard?.writeText(code).then(() => toast.success('Copié')).catch(() => {});
  return (
    <div className="relative">
      <pre tabIndex={0} className="bg-base border border-overlay/8 rounded-xl p-3 pr-10 text-xs text-ink-2 overflow-x-auto focus:outline-hidden focus-visible:ring-2 focus-visible:ring-primary/50"><code>{code}</code></pre>
      <button onClick={copy} aria-label="Copier" className="absolute top-2 right-2 p-1.5 rounded-lg text-ink-4 hover:text-ink-1 hover:bg-overlay/6"><Copy size={12} /></button>
    </div>
  );
}

export default function ApiDocs() {
  const [spec, setSpec] = useState(null);
  useEffect(() => { api.get('/v1/openapi.json').then(r => setSpec(r.data)).catch(() => setSpec(false)); }, []);
  if (spec === false) return <p className="p-6 text-sm text-red-400">Documentation indisponible.</p>;
  if (!spec) return <div className="p-6"><div className="h-40 rounded-2xl bg-overlay/2.5 animate-pulse" /></div>;
  const base = spec.servers?.[0]?.url || '/api/v1';
  const ops = Object.entries(spec.paths).flatMap(([path, methods]) => Object.entries(methods).map(([method, op]) => ({ path, method, op })));

  return (
    <div className="p-4 sm:p-6 space-y-6 max-w-4xl">
      <div className="flex flex-wrap items-start gap-3">
        <div className="min-w-0 flex-1">
          <h1 className="text-xl font-bold text-ink-1 flex items-center gap-2"><BookOpen size={20} className="text-primary-light" /> Documentation de l'API</h1>
          <p className="text-sm text-ink-3 mt-1"><Rich text={spec.info.description} /></p>
        </div>
        <div className="flex gap-2">
          <Link to="/api-keys" className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-overlay/8 text-xs text-ink-2 hover:text-ink-1"><KeyRound size={12} /> Clés API</Link>
          <a href="/api/v1/openapi.json" download="openapi.json" className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-overlay/8 text-xs text-ink-2 hover:text-ink-1"><Download size={12} /> OpenAPI (JSON)</a>
        </div>
      </div>

      <section className="bg-surface-card border border-overlay/6 rounded-2xl p-5 space-y-2">
        <h2 className="text-sm font-semibold text-ink-2">Adresse et authentification</h2>
        <p className="text-sm text-ink-2">Toutes les routes commencent par <code className="px-1 rounded bg-overlay/6">{base}</code>. Chaque requête porte la clé :</p>
        <CodeBlock code={'Authorization: Bearer tb_<id du serveur>_<64 caractères>'} />
        <p className="text-xs text-ink-4">Les erreurs répondent <code>{'{ "error": "…" }'}</code> avec le code HTTP : 401 (clé absente, invalide, révoquée ou expirée), 403 (permission manquante ou API désactivée sur le serveur), 404, 429 (trop de requêtes).</p>
      </section>

      {ops.map(({ path, method, op }) => {
        const params = op.parameters || [];
        const example = op.responses?.[200]?.content?.['application/json']?.example;
        const sample = path.replace(/\{(\w+)\}/g, (_, n) => (n === 'id' ? '42' : `<${n}>`));
        const curl = `curl${method === 'get' ? '' : ` -X ${method.toUpperCase()}`} -H "Authorization: Bearer $TICKETBOT_KEY" \\\n  "${base}${sample}${params.some(p => p.in === 'query') ? `?${params.filter(p => p.in === 'query').map(p => `${p.name}=${p.schema.enum?.[0] || '1'}`).join('&')}` : ''}"`;
        return (
          <section key={method + path} id={`${method}-${path}`} className="bg-surface-card border border-overlay/6 rounded-2xl p-5 space-y-3">
            <div className="flex flex-wrap items-center gap-2">
              <span className={`px-2 py-0.5 rounded-md border text-[11px] font-bold uppercase ${METHOD_CLS[method] || 'bg-overlay/6 text-ink-2'}`}>{method}</span>
              <code className="text-sm text-ink-1 font-semibold">{path}</code>
              <span className="text-sm text-ink-3">— {op.summary}</span>
              <span className="ml-auto text-[11px] text-ink-4">permission <code className="px-1 rounded bg-overlay/6 text-ink-2">{op['x-permission']}</code></span>
            </div>
            <p className="text-sm text-ink-2"><Rich text={op.description.split('\n\n')[0]} /></p>
            {params.length > 0 && (
              <table className="w-full text-xs">
                <thead><tr className="text-left text-ink-4"><th className="py-1 pr-3 font-medium">Paramètre</th><th className="py-1 pr-3 font-medium">Où</th><th className="py-1 font-medium">Description</th></tr></thead>
                <tbody>
                  {params.map(p => (
                    <tr key={p.name} className="border-t border-overlay/6">
                      <td className="py-1.5 pr-3"><code className="text-ink-1">{p.name}</code>{p.required && <span className="text-red-400"> *</span>}</td>
                      <td className="py-1.5 pr-3 text-ink-3">{p.in === 'path' ? 'chemin' : 'requête'}</td>
                      <td className="py-1.5 text-ink-2">{p.description}{p.schema?.enum ? ` (${p.schema.enum.join(', ')})` : ''}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            <p className="text-xs font-semibold text-ink-3">Exemple</p>
            <CodeBlock code={curl} />
            {example && (<><p className="text-xs font-semibold text-ink-3">Réponse</p><CodeBlock code={JSON.stringify(example, null, 2)} /></>)}
          </section>
        );
      })}
    </div>
  );
}
